import type { RadiologiPenunjang, Response } from '@/type'

import { get } from './api'

const getRadiologi = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<RadiologiPenunjang>> => {
  const response = await get(`/v1/radiologi/${noreg}`)

  return response.data
}

export { getRadiologi }
