import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout_border_no'
import Loading from '@/components/loading'
import { getRadiologi } from '@/services/radiologi'
import { constants } from '@/utils/constants'

import { RadiologiTable } from './radiologi-table'

export const KELOMPOK_RADIOLOGI = ['Radiologi', 'Citiscan']
export const KELOMPOK_PENUNJANG_LAIN = ['EKG', 'Echo', 'USG', 'Spirometri']

interface PenmedikRadiologiProps {
  isReport?: boolean
  noreg?: string
  no?: string
  kelompok?: string[]
  judul?: string
}

export default function PenmedikRadiologi({
  isReport = true,
  noreg = '',
  no,
  kelompok = KELOMPOK_RADIOLOGI,
  judul = 'PEMERIKSAAN RADIOLOGI',
}: PenmedikRadiologiProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.radiologi, noreg],
    queryFn: () => getRadiologi({ noreg: noreg! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  const ditampilkan = kelompok.map((item) => item.toLowerCase())
  const radiologi = (res?.radiologi ?? []).filter((item) =>
    ditampilkan.includes(item.nama_kelompok.trim().toLowerCase()),
  )

  const dokter = res?.dokter || '-'

  return (
    <LayoutBorderNo isReport={isReport} no={no}>
      <div className='p-4'>
        <h3 className='font-bold text-center py-3'>{judul}</h3>

        <RadiologiTable data={radiologi} />

        <div className='flex items-end justify-end my-8'>
          <div className='text-center flex flex-col items-center gap-4'>
            <p className='text-xs'>Dokter Penanggung Jawab</p>
            <QRCode value={dokter} className='h-[50px] w-[50px]' />
            <p className='text-xs'>{dokter}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
